<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { ElMessage } from 'element-plus';
import AsyncState from '../components/AsyncState.vue';
import { management, type ManagedUser, type CreateUser } from '../api/management';
import { label } from '../lib/format';
import { avatarValidation, replyStyles } from '../lib/profile';
import { tinoStyle } from '../lib/tino';
import { actor, refreshProfile } from '../auth';
const rows=ref<ManagedUser[]>([]),loading=ref(true),error=ref(''),query=ref(''),page=ref(1),total=ref(0);
const open=ref(false),editing=ref<ManagedUser>(),saving=ref(false),formError=ref(''),fileInput=ref<HTMLInputElement>();
const form=reactive<CreateUser & {nickname:string;bio:string;aiReplyStyle:ManagedUser['aiReplyStyle']}>({username:'',displayName:'',role:'STUDENT',studentNumber:'',password:'',nickname:'',bio:'',aiReplyStyle:'GUIDED'});
let loadId=0;
async function load(){const token=++loadId;loading.value=true;error.value='';try{const result=await management.users(page.value,query.value);if(token===loadId){rows.value=result.items;total.value=result.total;}}catch(e){if(token===loadId)error.value=(e as Error).message;}finally{if(token===loadId)loading.value=false;}}
async function edit(row?:ManagedUser){formError.value='';editing.value=undefined;Object.assign(form,{username:'',displayName:'',role:'STUDENT',studentNumber:'',password:'',nickname:'',bio:'',aiReplyStyle:'GUIDED'});try{if(row){const value=await management.user(row.id);editing.value=value;Object.assign(form,value,{studentNumber:value.studentNumber||'',password:''});}open.value=true;}catch(e){ElMessage.error((e as Error).message);}}
async function save(){saving.value=true;formError.value='';try{if(editing.value)await management.editUser(editing.value.id,{displayName:form.displayName,studentNumber:form.role==='STUDENT'?form.studentNumber:null,nickname:form.nickname,bio:form.bio,aiReplyStyle:form.aiReplyStyle});else await management.createUser({username:form.username,displayName:form.displayName,role:form.role,studentNumber:form.role==='STUDENT'?form.studentNumber:'',password:form.password});if(editing.value?.id===actor.value?.id)await refreshProfile();open.value=false;form.password='';ElMessage.success(editing.value?'用户资料已更新':'用户已添加');await load();}catch(e){formError.value=(e as Error).message;}finally{saving.value=false;}}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||!editing.value)return;const invalid=avatarValidation(file);if(invalid)return ElMessage.warning(invalid);saving.value=true;try{editing.value=await management.uploadAvatar(editing.value.id,file);if(editing.value.id===actor.value?.id)await refreshProfile();ElMessage.success('头像已更新');await load();}catch(e){ElMessage.error((e as Error).message);}finally{saving.value=false;}}
async function remove(){if(!editing.value)return;saving.value=true;try{editing.value=await management.removeAvatar(editing.value.id);if(editing.value.id===actor.value?.id)await refreshProfile();ElMessage.success('头像已移除');await load();}catch(e){ElMessage.error((e as Error).message);}finally{saving.value=false;}}
onMounted(load);
</script>
<template><div class="page"><div class="page-heading"><h1>用户管理</h1><el-button type="primary" @click="edit()">添加用户</el-button></div><div class="section-bar"><span>共 {{ total }} 人</span><el-input v-model="query" clearable placeholder="搜索账号、姓名或学号" class="search-input" @change="page=1;load()" @keyup.enter="page=1;load()" /></div><AsyncState :loading="loading" :error="error" :empty="!rows.length" empty-text="暂无符合条件的用户" @retry="load"><div class="panel table-panel"><el-table :data="rows"><el-table-column prop="username" label="账号" min-width="150"/><el-table-column prop="displayName" label="姓名" min-width="120"/><el-table-column label="角色" width="100"><template #default="{row}">{{ label(row.role) }}</template></el-table-column><el-table-column prop="studentNumber" label="学号" min-width="130"/><el-table-column prop="nickname" label="昵称" min-width="120"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑资料</el-button></template></el-table-column></el-table></div></AsyncState><el-pagination v-if="total>20" class="mt" v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="load"/><el-dialog v-model="open" :title="editing?'编辑用户资料':'添加用户'" width="620px" :close-on-click-modal="false" @closed="form.password='' "><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top" :disabled="saving" @submit.prevent="save"><div class="two-column"><el-form-item label="登录账号"><el-input v-model="form.username" :disabled="!!editing" maxlength="100" autocomplete="off"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role" :disabled="!!editing"><el-option label="学生" value="STUDENT"/><el-option label="教师" value="TEACHER"/><el-option label="管理员" value="ADMIN"/></el-select></el-form-item><el-form-item label="姓名"><el-input v-model="form.displayName" maxlength="100"/></el-form-item><el-form-item v-if="form.role==='STUDENT'" label="学号"><el-input v-model="form.studentNumber" maxlength="32"/></el-form-item></div><el-form-item v-if="!editing" label="初始密码"><el-input v-model="form.password" type="password" show-password autocomplete="new-password" placeholder="至少 8 位，包含字母和数字"/></el-form-item><template v-else><div class="admin-avatar"><img v-if="editing.avatarUrl" :src="editing.avatarUrl" alt="用户头像"/><el-button @click="fileInput?.click()">更换头像</el-button><el-button v-if="editing.avatarUrl" @click="remove">移除头像</el-button><span class="muted">头像修改立即保存</span><input ref="fileInput" hidden type="file" accept="image/png,image/jpeg" @change="upload"/></div><el-form-item label="昵称"><el-input v-model="form.nickname" maxlength="32"/></el-form-item><el-form-item label="个人简介"><el-input v-model="form.bio" type="textarea" :rows="3" maxlength="500" show-word-limit/></el-form-item><el-form-item label="AI 回复风格"><el-select v-model="form.aiReplyStyle"><el-option v-for="style in (editing?.tinoUnlocked ? [...replyStyles,tinoStyle] : replyStyles)" :key="style.value" :label="style.title" :value="style.value"/></el-select></el-form-item></template></el-form><template #footer><el-button :disabled="saving" @click="open=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">{{ editing?'保存资料':'添加用户' }}</el-button></template></el-dialog></div></template>
<style scoped>.admin-avatar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:4px 0 22px}.admin-avatar img{width:56px;height:56px;border-radius:12px;object-fit:cover}</style>
